SELECT customer_id, first_name || ' ' || last_name AS customer_name
      FROM customers
      ORDER BY customer_id;

CREATE OR REPLACE TEMP VIEW safe_customer_reporting AS
      SELECT customer_id, customer_name, region, lifetime_value
      FROM secure_customers;

      SELECT customer_id, customer_name, region, lifetime_value
      FROM safe_customer_reporting
      ORDER BY customer_id;
